insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"WINNER_LTE_4","title":"¿Al ganador le bastan 4 o menos?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"winner_lte","n":4},"priority":0,"cooldown":2,"tags":["resultado"]},{"code":"WINNER_BUCKET","title":"¿Cuántas anota el ganador?","description":"Elige el rango. Se corrige con el marcador final.","category":"resultado","difficulty":"medium","points":4,"answerType":"multiple","options":[{"id":"1a3","label":"1 a 3"},{"id":"4a6","label":"4 a 6"},{"id":"7a9","label":"7 a 9"},{"id":"10p","label":"10 o más"}],"rule":{"op":"buckets","fact":"winner_runs","buckets":[{"id":"1a3","label":"1 a 3","min":1,"max":3},{"id":"4a6","label":"4 a 6","min":4,"max":6},{"id":"7a9","label":"7 a 9","min":7,"max":9},{"id":"10p","label":"10 o más","min":10,"max":null}]},"priority":1,"cooldown":2,"tags":["resultado","rango"]},{"code":"LOSER_LTE_1","title":"¿El perdedor se quedará en 1 o menos?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"loser_lte","n":1},"priority":0,"cooldown":2,"tags":["defensiva"]},{"code":"LOSER_LTE_2","title":"¿El perdedor anotará 2 o menos?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"loser_lte","n":2},"priority":0,"cooldown":2,"tags":["defensiva"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;